'use client';
import { useEffect, useState } from 'react';
import { Activity, Boxes, GitBranch, Layers } from 'lucide-react';
import { apiClient, type AnalyticsOverview } from '@/lib/api-client';
import { BarChart } from './charts/bar-chart';
import { DonutChart } from './charts/donut-chart';
export function ProjectAnalytics({ projectId }: { projectId: string }) { const [data, setData] = useState<AnalyticsOverview | null>(null); const [error, setError] = useState(''); useEffect(() => { void apiClient.analytics.overview(projectId).then((result) => result.success && result.data ? setData(result.data) : setError(result.error?.message || 'Could not load analytics.')); }, [projectId]); if (error) return <div className="data-alert" role="alert">{error}</div>; if (!data) return <div className="data-state" role="status">Loading project intelligence…</div>; const cards = [['APIs', data.metrics.apis, Boxes], ['Versions', data.metrics.versions, GitBranch], ['Endpoints', data.metrics.endpoints, Layers], ['Dependencies', data.metrics.dependencies, Activity]] as const; return <div className="workspace-page"><div className="project-hero"><div><p className="page-kicker">Project intelligence</p><h2>Operational overview</h2><p>Signals from the APIs and relationships registered in this project.</p></div></div><div className="analytics-metrics">{cards.map(([label, value, Icon]) => <article key={label}><Icon size={17}/><span>{label}</span><b>{value}</b></article>)}</div><div className="analytics-grid"><section className="workspace-section"><div className="section-title-row"><div><p className="page-kicker">Registry growth</p><h3>APIs registered over time</h3></div></div><BarChart items={data.growth.map((item) => ({ label: new Date(item.date).toLocaleDateString(undefined, { month: 'short', year: 'numeric' }), value: item.value }))}/></section><section className="workspace-section"><div className="section-title-row"><div><p className="page-kicker">Lifecycle</p><h3>API status distribution</h3></div></div><DonutChart items={data.lifecycle.map((item) => ({ label: item.lifecycle, value: item.value }))}/></section></div><section className="workspace-section"><div className="section-title-row"><div><p className="page-kicker">Activity timeline</p><h3>Recent project events</h3></div></div>{data.activity.length ? <div className="activity-list">{data.activity.map((event) => <article key={event.id}><span className="timeline-dot"/><div><b>{event.summary}</b><time>{new Date(event.occurredAt).toLocaleString()}</time></div></article>)}</div> : <div className="empty-state"><b>No activity recorded yet</b><p>Register an API or version to start building project history.</p></div>}</section></div>; }
